# cc-proxy

Local Anthropic proxy for Claude Code: model aliases (haiku/sonnet/opus/fable) go to other providers'
Anthropic-compatible endpoints with fallbacks, ending at Claude. Guide and measured facts:
`~/chat/docs/agent/261111-claude-code-proxy-opencode-go-xai.md`.

- Pure logic lives in `config.ts`, `normalize.ts`, `stats.ts` (`bun test`); `server.ts` is I/O.
- One request transform for every non-Anthropic provider (strictest wins); provider differences are only
  URL, auth and extra headers in `upstreams.ts`. Do not branch routing on a provider name.
- Credentials come from the central `auth` store (`dev/auth`, `~/.config/auth/credentials.json`), read via `../auth/client/central-auth.ts`; an expired OAuth token is refreshed by `auth refresh`. Never pi's `auth.json`.
- Consumers: Claude Code plugin `~/.agents/plugins/proxy`, dashboard `apps/server/src/cc_proxy.rs` +
  `apps/client/src/lib/settings/cc-proxy-section.svelte`. Keep `/_proxy/*` shapes in step with them.
- After a change: `bun test`, `bunx tsc -p .`, `systemctl --user restart cc-proxy`, then
  `claude -p "say: pong" --model haiku </dev/null` and `cc-proxy status`.
{
	"name": "cc-proxy",
	"private": true,
	"type": "module",
	"scripts": {
		"test": "bun test"
	}
}
/**
 * pi와 공유하는 두 가지: 모델이 thinking off를 받는지(pi 카탈로그), 다른 업체로 보낼 때 system 끝에 붙일
 * 공통 층(easy-harness `sources/common.md`).
 *
 * off: pi의 `models-store.json`에 `models.json` `modelOverrides`를 겹친 `thinkingLevelMap.off`를 본다.
 * `null`이면 그 모델은 off가 없다(xAI grok-4.7은 `thinking: disabled`를 200으로 받지만 무시하고 생각한다,
 * 261111 실측). 그러면 pi `clampThinkingLevel`처럼 low로 올린다. 업체 이름이 아니라 카탈로그로 판단한다.
 *
 * 공통 층: deepseek-v4.1-flash에서 추론 −53%, grok-4.7에서 출력 −12%(정답 수 같음,
 * `~/.pi/agent/docs/provider/261111-pi-flash-thinking-bench.md`). 문구는 pi와 같은 파일 하나다.
 */
import { existsSync, readFileSync, statSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import type { Effort } from "./config.ts";

type Json = Record<string, unknown>;

const isRecord = (value: unknown): value is Json => !!value && typeof value === "object" && !Array.isArray(value);

/** 카탈로그(store + overrides)에서 그 모델의 off 지원 여부. 모르는 모델은 false(low로 안전하게). */
export function offAllowed(store: unknown, overrides: unknown, provider: string, id: string): boolean {
	const models = isRecord(store) && isRecord(store[provider]) ? store[provider].models : undefined;
	const model = Array.isArray(models) ? models.find((entry) => isRecord(entry) && entry.id === id) : undefined;
	if (!isRecord(model)) return false;
	const providers = isRecord(overrides) && isRecord(overrides.providers) ? overrides.providers : {};
	const entry = isRecord(providers[provider]) ? providers[provider] : {};
	const patch = isRecord(entry.modelOverrides) && isRecord(entry.modelOverrides[id]) ? entry.modelOverrides[id] : {};
	if ((typeof patch.reasoning === "boolean" ? patch.reasoning : model.reasoning) === false) return true;
	const patchMap = isRecord(patch.thinkingLevelMap) ? patch.thinkingLevelMap : {};
	const map = isRecord(model.thinkingLevelMap) ? model.thinkingLevelMap : {};
	const off = "off" in patchMap ? patchMap.off : map.off;
	return off !== null;
}

/** 보낼 effort: off를 못 받는 모델이면 low. */
export function sendEffort(effort: Effort | undefined, allowsOff: boolean): Effort | undefined {
	return effort === "off" && !allowsOff ? "low" : effort;
}

const piDir = () => process.env.CC_PROXY_PI_DIR ?? join(homedir(), ".pi", "agent");

function cached<T>(paths: () => string[], build: (texts: (string | undefined)[]) => T): () => T {
	let key = "";
	let value: T | undefined;
	return () => {
		const files = paths();
		const next = files.map((path) => (existsSync(path) ? `${statSync(path).mtimeMs}` : "-")).join("|");
		if (value === undefined || next !== key) {
			key = next;
			value = build(files.map((path) => (existsSync(path) ? readFileSync(path, "utf8") : undefined)));
		}
		return value;
	};
}

const parse = (text: string | undefined): unknown => {
	try {
		return text ? JSON.parse(text) : undefined;
	} catch {
		return undefined;
	}
};

const catalog = cached(
	() => [join(piDir(), "models-store.json"), join(piDir(), "models.json")],
	([store, overrides]) => ({ store: parse(store), overrides: parse(overrides) }),
);

/** I/O: 지금 카탈로그로 `offAllowed`. 파일이 바뀌면 다시 읽는다. */
export function catalogAllowsOff(provider: string, id: string): boolean {
	const { store, overrides } = catalog();
	return offAllowed(store, overrides, provider, id);
}

export function commonPath(): string {
	return process.env.CC_PROXY_COMMON_FILE ?? join(piDir(), "extensions", "easy-harness", "sources", "common.md");
}

const common = cached(
	() => [commonPath()],
	([text]) => text?.trim() ?? "",
);

/** I/O: 공통 층 문구. 파일이 없으면 "" (층 없음). */
export function commonText(): string {
	return common();
}
/**
 * cc-proxy 설정 — `~/.config/cc-proxy/config.json`.
 *
 * Claude Code 별칭(haiku/sonnet/opus/fable)마다 프록시 대상 체인을 둔다. 체인 앞에서부터 시도하고,
 * 모두 실패하면 원래 Claude 모델(Anthropic 직행)로 간다. 체인이 비면 그 별칭은 그대로 Anthropic이다.
 * `enabled: false`면 모든 요청이 그대로 Anthropic으로 간다(Claude Code는 세션 중에도 프록시를 거친다).
 */
import { existsSync, mkdirSync, readFileSync, renameSync, statSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { homedir } from "node:os";

export const ALIASES = ["haiku", "sonnet", "opus", "fable"] as const;
export type Alias = (typeof ALIASES)[number];
/** `off` = `thinking: {type: "disabled"}`. pi 카탈로그에 off가 없는 모델이면 low로 보낸다(`levels.ts`). */
export const EFFORTS = ["off", "low", "medium", "high", "xhigh", "max"] as const;
export type Effort = (typeof EFFORTS)[number];

/** 체인 한 칸: `provider/model`. `effort`가 있으면 Claude Code가 보낸 effort 대신 이 값을 보낸다. */
export type Target = { model: string; effort?: Effort };
/** `common: false`면 그 별칭은 공통 층(`levels.ts` `commonText`)을 붙이지 않는다. 기본은 붙인다. */
export type Route = { chain: Target[]; common?: false };
export type Config = {
	enabled: boolean;
	routes: Record<Alias, Route>;
	/** 429·5xx·연결·인증 실패 뒤 그 대상을 건너뛰는 시간. */
	cooldownSeconds: number;
	/** true(기본)면 서브에이전트 요청(`x-claude-code-agent-id` 헤더)만 체인을 탄다. 메인 대화와 보조 호출은
	 *  모델이 무엇이든 Anthropic 직행이다(`proxiable`). */
	subagentsOnly: boolean;
	/** 공통 층(과추론을 막는 두 줄) 전체 스위치. 기본 true. 끄면 별칭 설정과 무관하게 붙이지 않는다. */
	common: boolean;
};

/** 이 별칭의 요청에 공통 층을 붙이는가: 전체 스위치가 켜져 있고 별칭이 끄지 않았을 때. */
export function commonOn(config: Config, alias: Alias | null): boolean {
	return config.common && !(alias && config.routes[alias].common === false);
}

export const PORT = Number(process.env.CC_PROXY_PORT ?? 45870);

/** Claude Code 2.1.322는 서브에이전트의 API 요청에만 `x-claude-code-agent-id`를 붙인다(메인에는 없음, 261111 실측). */
export const AGENT_HEADER = "x-claude-code-agent-id";

/** 체인을 탈 요청인가: `subagentsOnly`면 서브에이전트 요청만. */
export function proxiable(config: Config, headers: Headers): boolean {
	return !config.subagentsOnly || headers.has(AGENT_HEADER);
}

export const DEFAULT_CONFIG: Config = {
	enabled: true,
	routes: {
		haiku: { chain: [{ model: "opencode-go/deepseek-v4.1-flash" }] },
		sonnet: { chain: [{ model: "xai/grok-4.7" }] },
		opus: { chain: [] },
		fable: { chain: [] },
	},
	cooldownSeconds: 60,
	subagentsOnly: true,
	common: true,
};

export function configDir(): string {
	return process.env.CC_PROXY_CONFIG_DIR ?? join(homedir(), ".config", "cc-proxy");
}

/** Claude 모델 ID(`claude-haiku-5-5`, `claude-opus-5-5[1m]`)의 별칭. Claude가 아니면 null. */
export function aliasOf(model: unknown): Alias | null {
	if (typeof model !== "string") return null;
	const match = /^claude-(haiku|sonnet|opus|fable)\b/.exec(model.toLowerCase());
	return (match?.[1] as Alias | undefined) ?? null;
}

/** `provider/model` → 둘로. 형식이 틀리면 null. */
export function splitTarget(model: string): { provider: string; id: string } | null {
	const slash = model.indexOf("/");
	if (slash <= 0 || slash === model.length - 1) return null;
	return { provider: model.slice(0, slash), id: model.slice(slash + 1) };
}

/** 검증하고 빠진 칸은 기본값으로 채운다. 틀리면 이유를 던진다. */
export function validate(input: unknown, providers: readonly string[]): Config {
	if (!input || typeof input !== "object") throw new Error("config must be an object");
	const raw = input as Partial<Config> & { routes?: Partial<Record<string, Partial<Route>>> };
	const routes = {} as Record<Alias, Route>;
	for (const alias of ALIASES) {
		const chain = raw.routes?.[alias]?.chain ?? DEFAULT_CONFIG.routes[alias].chain;
		if (!Array.isArray(chain)) throw new Error(`${alias}: chain must be a list`);
		if (chain.length > 8) throw new Error(`${alias}: at most 8 targets`);
		const seen = new Set<string>();
		const common = raw.routes?.[alias]?.common;
		if (common !== undefined && typeof common !== "boolean") throw new Error(`${alias}: common is true/false`);
		routes[alias] = {
			...(common === false ? { common: false as const } : {}),
			chain: chain.map((target) => {
				if (!target || typeof target.model !== "string") throw new Error(`${alias}: target needs a model`);
				const split = splitTarget(target.model);
				if (!split) throw new Error(`${alias}: ${target.model} is not provider/model`);
				if (!providers.includes(split.provider)) {
					throw new Error(`${alias}: provider ${split.provider} is not supported (${providers.join(", ")})`);
				}
				if (seen.has(target.model)) throw new Error(`${alias}: ${target.model} is listed twice`);
				seen.add(target.model);
				if (target.effort !== undefined && !EFFORTS.includes(target.effort)) {
					throw new Error(`${alias}: effort is ${EFFORTS.join("/")}`);
				}
				return target.effort ? { model: target.model, effort: target.effort } : { model: target.model };
			}),
		};
	}
	const cooldownSeconds = raw.cooldownSeconds ?? DEFAULT_CONFIG.cooldownSeconds;
	if (!(Number.isFinite(cooldownSeconds) && cooldownSeconds >= 0 && cooldownSeconds <= 3600)) {
		throw new Error("cooldownSeconds is 0–3600");
	}
	const subagentsOnly = raw.subagentsOnly ?? DEFAULT_CONFIG.subagentsOnly;
	if (typeof subagentsOnly !== "boolean") throw new Error("subagentsOnly is true/false");
	const common = raw.common ?? DEFAULT_CONFIG.common;
	if (typeof common !== "boolean") throw new Error("common is true/false");
	return { enabled: raw.enabled ?? DEFAULT_CONFIG.enabled, routes, cooldownSeconds, subagentsOnly, common };
}

/** 파일 버전: 저장할 때 읽은 버전과 다르면(그 사이 손으로 고쳤으면) 거절한다. */
export function versionOf(path: string): string {
	try {
		const stat = statSync(path);
		return `${stat.mtimeMs}-${stat.size}`;
	} catch {
		return "missing";
	}
}

export function configPath(): string {
	return join(configDir(), "config.json");
}

export function readConfig(providers: readonly string[]): { config: Config; version: string; error?: string } {
	const path = configPath();
	const version = versionOf(path);
	if (!existsSync(path)) return { config: DEFAULT_CONFIG, version };
	try {
		return { config: validate(JSON.parse(readFileSync(path, "utf8")), providers), version };
	} catch (cause) {
		return { config: DEFAULT_CONFIG, version, error: cause instanceof Error ? cause.message : String(cause) };
	}
}

export function writeConfig(config: Config): string {
	const path = configPath();
	mkdirSync(dirname(path), { recursive: true });
	const tmp = `${path}.${process.pid}.tmp`;
	writeFileSync(tmp, `${JSON.stringify(config, null, "\t")}\n`);
	renameSync(tmp, path);
	return versionOf(path);
}

